import random
from collections import defaultdict, Counter
seq = ""
with open("region.fasta") as f:
    for line in f:
        if not line.startswith(">"):
            seq += line.strip().upper()
n=len(seq)
comp = str.maketrans("ACGT","TGCA")
def rc(s): return s.translate(comp)[::-1]
code={}
bases="TCAG"; aas="FFLLSSSSYY**CC*WLLLLPPPPHHQQRRRRIIIMTTTTNNKKSSRRVVVVAAAADDEEGGGG"
i=0
for a in bases:
    for b in bases:
        for c in bases:
            code[a+b+c]=aas[i]; i+=1
def translate(s): return "".join(code[s[i:i+3]] for i in range(0,len(s)-2,3))
def longest_orf_atg(s):
    m=0
    for strand in (s, rc(s)):
        for f in range(3):
            prot=translate(strand[f:]); run=""
            for ch in prot+"*":
                if ch=='*':
                    k=run.find('M')
                    if k!=-1: m=max(m,len(run)-k)
                    run=""
                else: run+=ch
    return m

# first-order Markov from observed transitions
trans=defaultdict(Counter)
for i in range(n-1):
    trans[seq[i]][seq[i+1]]+=1
alphabet="ACGT"
probs={a:[trans[a][b] for b in alphabet] for a in alphabet}
for a in alphabet:
    tot=sum(probs[a]); probs[a]=[x/tot for x in probs[a]]
